import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 960;
const CX = W / 2;

const COLORS = {
  text: { fill: '#e3f2fd', stroke: '#1976d2' },
  img: { fill: '#e8f5e9', stroke: '#4caf50' },
  attn: { fill: '#fce4ec', stroke: '#c62828' },
  norm: { fill: '#e0f2f1', stroke: '#00897b' },
  gate: { fill: '#fff3e0', stroke: '#e65100' },
  proj: { fill: '#ede7f6', stroke: '#4527a0' },
  weight: { fill: '#f1f8e8', stroke: '#64748b' },
  out: { fill: '#e8f5e9', stroke: '#2e7d32' },
  latent: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const MAT_H = 80;
const SEQ_W = 200;
const STEP_GAP = 120;
const BOX_TO_ROW = 100;
const ROW_GAP = 90;
const WEIGHT_W = 140;
const WEIGHT_H = 80;

// ═══════════════════════════════════════════════════════════════════════════════
// Helpers
// ═══════════════════════════════════════════════════════════════════════════════

interface VlStep extends StepInfo {}

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}
function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}
function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = 800
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 24).attr('cy', y + BOX_H / 2)
    .attr('r', 14).attr('fill', stroke);
  lbl(g, cx - w / 2 + 24, y + BOX_H / 2 + 1, String(sn), { size: 12, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 48, y + BOX_H / 2 - 6, title, { size: 13, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 48, y + BOX_H / 2 + 10, formula, { size: 9, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.2 + 28, 200);
  const h = 28;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy, text, { size: 8.5, color, font: 'monospace' });
}

function seqMatrix(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = SEQ_W, h = MAT_H
): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke,
    cols: 8, rows: 5, dimTop: 'S', dimRight: 'D',
  });
}

function weight(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill = COLORS.weight.fill, stroke = COLORS.weight.stroke,
  w = WEIGHT_W, h = WEIGHT_H
): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 5,
  });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string, r = 18): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', r)
    .attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 14, weight: '700', color });
}

function lnBadge(g: Gsel, cx: number, cy: number, text = 'LayerNorm', stroke = COLORS.norm.stroke): void {
  const w = 130;
  const h = 30;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', COLORS.norm.fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 9, weight: '600', color: stroke });
}

function activationBadge(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string): void {
  const w = 130;
  const h = 34;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 11, weight: '700', color: stroke });
}

function paramSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 120;
  const h = 34;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): VlStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

/** Standard matmul row: input → × → weight → output, centered at cx */
function matmulRow(
  g: Gsel, cx: number, cy: number,
  inLabel: string, inSub: string, inFill: string, inStroke: string,
  wLabel: string, wSub: string, wFill: string, wStroke: string,
  outLabel: string, outSub: string, outFill: string, outStroke: string,
  inW = 160, wW = WEIGHT_W, outW = 160
): void {
  const gap1 = 36;
  const gap2 = 36;
  const totalW = inW + gap1 + 36 + gap2 + wW + gap1 + 36 + gap2 + outW;
  let x = cx - totalW / 2;

  const inCx = x + inW / 2;
  seqMatrix(g, inCx, cy, inLabel, inSub, inFill, inStroke, inW, MAT_H);
  x += inW;

  const opX = x + gap1 / 2 + 18;
  opCircle(g, opX, cy, '×', inStroke);
  drawArrow(g as Sel, inCx + inW / 2 + 4, cy, opX - 20, cy, { color: inStroke });
  x += gap1 + 36;

  const wCx = x + wW / 2;
  weight(g, wCx, cy, wLabel, wSub, wFill, wStroke, wW, WEIGHT_H);
  drawArrow(g as Sel, opX + 20, cy, wCx - wW / 2 - 4, cy, { color: inStroke });
  x += wW;

  const op2X = x + gap2 / 2 + 18;
  lbl(g, op2X, cy, '=', { size: 14, weight: '700', color: '#64748b' });
  x += gap2 + 36;

  const outCx = x + outW / 2;
  seqMatrix(g, outCx, cy, outLabel, outSub, outFill, outStroke, outW, MAT_H);
}

// ═══════════════════════════════════════════════════════════════════════════════
// Cross-Attention (Flamingo-style) — 6 steps
// ═══════════════════════════════════════════════════════════════════════════════

function renderCrossAttention(
  g: Gsel, startY: number, seqLen: number, nPatches: number, dModel: number, nHeads: number
): { steps: VlStep[]; y: number } {
  const steps: VlStep[] = [];
  let stepId = 0;
  let y = startY;
  const dHead = Math.floor(dModel / nHeads);

  // ── Step 1: Input ──────────────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-input', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Input Representations',
      `text: [${seqLen}, ${dModel}]   image: [${nPatches}, ${dModel}]`,
      COLORS.text.fill, COLORS.text.stroke);

    const rowY = h + BOX_TO_ROW;
    seqMatrix(gs, CX - 200, rowY, 'text', `[${seqLen}, ${dModel}]`, COLORS.text.fill, COLORS.text.stroke);
    lbl(gs, CX - 200, rowY - MAT_H / 2 - 12, 'Text Tokens', { size: 9, color: COLORS.text.stroke, weight: '600' });
    seqMatrix(gs, CX + 200, rowY, 'image', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke);
    lbl(gs, CX + 200, rowY - MAT_H / 2 - 12, 'Image Tokens', { size: 9, color: COLORS.img.stroke, weight: '600' });

    steps.push(makeStep(stepId, 'Input', 'Input Representations',
      `text [${seqLen}, ${dModel}], image [${nPatches}, ${dModel}]`,
      'Text tokens from the language model and image tokens from the vision encoder.',
      'step-input', COLORS.text.stroke, COLORS.text.fill));
    y = rowY + MAT_H / 2 + STEP_GAP;
  }

  // ── Step 2: Q projection (text → Q) ────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-q-proj', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Query Projection (from Text)',
      `Q = text · W_q   →  [${seqLen}, ${dModel}]`,
      COLORS.text.fill, COLORS.text.stroke);

    arrowDown(gs, CX - 200, y, h, COLORS.text.stroke);

    const rowY = h + BOX_TO_ROW;
    matmulRow(gs, CX, rowY,
      'text', `[${seqLen}, ${dModel}]`, COLORS.text.fill, COLORS.text.stroke,
      'W_q', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.text.stroke,
      'Q', `[${seqLen}, ${dModel}]`, COLORS.text.fill, COLORS.attn.stroke);

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `text [${seqLen}, ${dModel}] · W_q [${dModel}, ${dModel}] = Q [${seqLen}, ${dModel}]`, COLORS.text.stroke);

    steps.push(makeStep(stepId, 'Q', 'Query Projection', `Q = text · W_q`,
      'Text tokens are projected to queries. Text provides the "questions" to ask about the image.',
      'step-q-proj', COLORS.text.stroke, COLORS.text.fill,
      [`Q = text @ W_q   # [${seqLen}, ${dModel}]`]));
    y = rowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 3: K, V projection (image → K, V) ────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-kv-proj', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Key & Value Projections (from Image)',
      `K = image · W_k,  V = image · W_v   →  [${nPatches}, ${dModel}]`,
      COLORS.img.fill, COLORS.img.stroke);

    arrowDown(gs, CX + 200, y, h, COLORS.img.stroke);

    // K row
    const kRowY = h + BOX_TO_ROW;
    matmulRow(gs, CX, kRowY,
      'image', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke,
      'W_k', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.img.stroke,
      'K', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.attn.stroke);

    shapeEq(gs, CX, kRowY + MAT_H / 2 + 24,
      `image [${nPatches}, ${dModel}] · W_k [${dModel}, ${dModel}] = K [${nPatches}, ${dModel}]`, COLORS.img.stroke);

    // V row
    const vRowY = kRowY + MAT_H / 2 + 24 + ROW_GAP + MAT_H / 2;
    arrowDown(gs, CX - 220, kRowY + MAT_H / 2, vRowY - MAT_H / 2, COLORS.img.stroke);

    matmulRow(gs, CX, vRowY,
      'image', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke,
      'W_v', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.img.stroke,
      'V', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.attn.stroke);

    shapeEq(gs, CX, vRowY + MAT_H / 2 + 24,
      `image [${nPatches}, ${dModel}] · W_v [${dModel}, ${dModel}] = V [${nPatches}, ${dModel}]`, COLORS.img.stroke);

    steps.push(makeStep(stepId, 'KV', 'Key & Value Projections', `K,V = image · W_k,W_v`,
      'Image tokens are projected to keys and values. These represent the "answers" the image can provide.',
      'step-kv-proj', COLORS.img.stroke, COLORS.img.fill,
      [`K = image @ W_k   # [${nPatches}, ${dModel}]`, `V = image @ W_v   # [${nPatches}, ${dModel}]`]));
    y = vRowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 4: Attention scores ──────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-scores', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Attention Score Computation',
      `scores = Q · K^T / √${dHead}  →  [${seqLen}, ${nPatches}]  (${nHeads} heads, d_head=${dHead})`,
      COLORS.attn.fill, COLORS.attn.stroke);

    arrowDown(gs, CX, y, h, COLORS.attn.stroke);

    // Q · K^T / √d → scores  (spacious layout)
    const scoreRowY = h + BOX_TO_ROW;
    const qX = CX - 280;
    const opX = CX - 150;
    const ktX = CX - 20;
    const arrowX = CX + 80;
    const scX = CX + 220;

    seqMatrix(gs, qX, scoreRowY, 'Q', `[${seqLen}, ${dModel}]`, COLORS.text.fill, COLORS.attn.stroke, 150, MAT_H);
    opCircle(gs, opX, scoreRowY, '×', COLORS.attn.stroke);
    drawArrow(gs as Sel, qX + 75 + 4, scoreRowY, opX - 20, scoreRowY, { color: COLORS.attn.stroke });

    // K^T (tall thin matrix)
    const ktW = 44;
    const ktH = 120;
    drawMatrixBlock(gs as Sel, ktX - ktW / 2, scoreRowY - ktH / 2, {
      width: ktW, height: ktH, label: 'K^T', sublabel: `[${dModel}, ${nPatches}]`,
      fill: COLORS.img.fill, stroke: COLORS.attn.stroke, cols: 3, rows: 7,
    });
    lbl(gs, ktX, scoreRowY - ktH / 2 - 10, 'transposed', { size: 7, color: COLORS.muted });
    drawArrow(gs as Sel, opX + 20, scoreRowY, ktX - ktW / 2 - 4, scoreRowY, { color: COLORS.attn.stroke });

    // / √d → scores
    lbl(gs, arrowX, scoreRowY - 6, '/ √d', { size: 10, weight: '600', color: COLORS.attn.stroke });
    lbl(gs, arrowX, scoreRowY + 8, '→', { size: 14, weight: '700', color: COLORS.attn.stroke });
    drawArrow(gs as Sel, ktX + ktW / 2 + 4, scoreRowY, arrowX - 24, scoreRowY, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, arrowX + 24, scoreRowY, scX - 80 - 4, scoreRowY, { color: COLORS.attn.stroke });

    seqMatrix(gs, scX, scoreRowY, 'scores', `[${seqLen}, ${nPatches}]`, COLORS.attn.fill, COLORS.attn.stroke, 150, 56);

    shapeEq(gs, CX, scoreRowY + ktH / 2 + 20,
      `Q [${seqLen}, ${dModel}] · K^T [${dModel}, ${nPatches}] / √${dHead} → scores [${seqLen}, ${nPatches}]`,
      COLORS.attn.stroke);

    // Softmax row
    const softY = scoreRowY + ktH / 2 + 20 + ROW_GAP;
    seqMatrix(gs, CX - 170, softY, 'scores', `[${seqLen}, ${nPatches}]`, COLORS.attn.fill, COLORS.attn.stroke, 150, 56);
    activationBadge(gs, CX, softY, 'softmax', COLORS.attn.fill, COLORS.attn.stroke);
    drawArrow(gs as Sel, CX - 170 + 75 + 4, softY, CX - 65 - 4, softY, { color: COLORS.attn.stroke });
    seqMatrix(gs, CX + 170, softY, 'weights', `[${seqLen}, ${nPatches}]`, '#fff5f5', COLORS.attn.stroke, 150, 56);
    drawArrow(gs as Sel, CX + 65 + 4, softY, CX + 170 - 75 - 4, softY, { color: COLORS.attn.stroke });

    shapeEq(gs, CX, softY + 40, `softmax(scores) → weights [${seqLen}, ${nPatches}]  (probabilities over image patches)`, COLORS.attn.stroke);

    steps.push(makeStep(stepId, 'Scores', 'Attention Scores',
      `softmax(Q·K^T/√d)`,
      `Each text token computes attention weights over all ${nPatches} image patches. ${nHeads} heads with d_head=${dHead}.`,
      'step-scores', COLORS.attn.stroke, COLORS.attn.fill,
      [`scores = Q @ K.T / math.sqrt(${dHead})   # [${nHeads}, ${seqLen}, ${nPatches}]`,
       `weights = softmax(scores, dim=-1)        # attention probabilities`]));
    y = softY + 40 + STEP_GAP;
  }

  // ── Step 5: Weighted sum + output projection ──────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-attn-out', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Weighted Sum + Output Projection',
      `attn_out = weights · V  →  [${seqLen}, ${dModel}]  then  attn_proj = attn_out · W_o`,
      COLORS.attn.fill, COLORS.attn.stroke);

    arrowDown(gs, CX, y, h, COLORS.attn.stroke);

    // weights × V row
    const wvRowY = h + BOX_TO_ROW;
    matmulRow(gs, CX, wvRowY,
      'weights', `[${seqLen}, ${nPatches}]`, '#fff5f5', COLORS.attn.stroke,
      'V', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.attn.stroke,
      'attn_out', `[${seqLen}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke,
      160, 130, 170);

    shapeEq(gs, CX, wvRowY + MAT_H / 2 + 24,
      `weights [${seqLen}, ${nPatches}] · V [${nPatches}, ${dModel}] = attn_out [${seqLen}, ${dModel}]`, COLORS.attn.stroke);

    // Output projection row
    const outRowY = wvRowY + MAT_H / 2 + 24 + ROW_GAP + MAT_H / 2;
    arrowDown(gs, CX + 250, wvRowY + MAT_H / 2, outRowY - MAT_H / 2, COLORS.attn.stroke);

    matmulRow(gs, CX, outRowY,
      'attn_out', `[${seqLen}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke,
      'W_o', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.proj.stroke,
      'attn_proj', `[${seqLen}, ${dModel}]`, COLORS.proj.fill, COLORS.proj.stroke,
      170, WEIGHT_W, 170);

    shapeEq(gs, CX, outRowY + MAT_H / 2 + 24,
      `attn_out [${seqLen}, ${dModel}] · W_o [${dModel}, ${dModel}] = attn_proj [${seqLen}, ${dModel}]  (${nHeads}h, d_h=${dHead})`,
      COLORS.proj.stroke);

    steps.push(makeStep(stepId, 'AttnOut', 'Weighted Sum + Proj',
      `weights·V → ·W_o`,
      `Weighted sum of V produces attention output, then projected back to d_model via W_o.`,
      'step-attn-out', COLORS.attn.stroke, COLORS.attn.fill,
      [`attn_out = weights @ V        # [${seqLen}, ${dModel}]`,
       `attn_proj = attn_out @ W_o   # output projection`]));
    y = outRowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 6: Gated residual fusion ─────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-gate', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Gated Residual Fusion',
      `output = LayerNorm(text + gate ⊙ attn_proj)  →  [${seqLen}, ${dModel}]`,
      COLORS.gate.fill, COLORS.gate.stroke);

    arrowDown(gs, CX, y, h, COLORS.gate.stroke);

    // Sub-row A: Gating  —  attn_proj ⊙ σ(W_g) → gated
    const gateRowY = h + BOX_TO_ROW;
    seqMatrix(gs, CX - 250, gateRowY, 'attn_proj', `[${seqLen}, ${dModel}]`, COLORS.proj.fill, COLORS.proj.stroke, 160, MAT_H);
    opCircle(gs, CX - 80, gateRowY, '⊙', COLORS.gate.stroke);
    drawArrow(gs as Sel, CX - 250 + 80 + 4, gateRowY, CX - 80 - 20, gateRowY, { color: COLORS.gate.stroke });
    lbl(gs, CX - 80, gateRowY - 28, 'element-wise gate', { size: 7, color: COLORS.gate.stroke, weight: '600' });

    // gate vector
    const gateVecW = 110;
    gs.append('rect').attr('x', CX + 30 - gateVecW / 2).attr('y', gateRowY - 16).attr('width', gateVecW).attr('height', 32)
      .attr('rx', 4).attr('fill', COLORS.gate.fill).attr('stroke', COLORS.gate.stroke).attr('stroke-width', 1);
    lbl(gs, CX + 30, gateRowY + 1, 'σ(W_g)', { size: 9, weight: '600', color: COLORS.gate.stroke });
    drawArrow(gs as Sel, CX + 30 - gateVecW / 2 - 4, gateRowY, CX - 80 + 20, gateRowY, { color: COLORS.gate.stroke });

    seqMatrix(gs, CX + 220, gateRowY, 'gated', `[${seqLen}, ${dModel}]`, COLORS.gate.fill, COLORS.gate.stroke, 160, MAT_H);
    drawArrow(gs as Sel, CX - 80 + 20, gateRowY, CX + 220 - 80 - 4, gateRowY, { color: COLORS.gate.stroke });

    shapeEq(gs, CX, gateRowY + MAT_H / 2 + 24,
      `gated = σ(W_g) ⊙ attn_proj  →  [${seqLen}, ${dModel}]`, COLORS.gate.stroke);

    // Sub-row B: Residual add  —  gated + text → sum
    const addRowY = gateRowY + MAT_H / 2 + 24 + ROW_GAP + MAT_H / 2;
    arrowDown(gs, CX + 220, gateRowY + MAT_H / 2, addRowY - MAT_H / 2, COLORS.gate.stroke);

    seqMatrix(gs, CX - 250, addRowY, 'gated', `[${seqLen}, ${dModel}]`, COLORS.gate.fill, COLORS.gate.stroke, 160, MAT_H);
    opCircle(gs, CX - 60, addRowY, '+', COLORS.out.stroke);
    drawArrow(gs as Sel, CX - 250 + 80 + 4, addRowY, CX - 60 - 20, addRowY, { color: COLORS.gate.stroke });

    seqMatrix(gs, CX + 120, addRowY, 'text', `[${seqLen}, ${dModel}]`, COLORS.text.fill, COLORS.text.stroke, 150, MAT_H);
    lbl(gs, CX + 30, addRowY - 16, 'residual', { size: 7, color: COLORS.text.stroke });
    drawArrow(gs as Sel, CX + 120 - 75 - 4, addRowY, CX - 60 + 20, addRowY, { color: COLORS.text.stroke });

    seqMatrix(gs, CX + 320, addRowY, 'sum', `[${seqLen}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 140, MAT_H);
    drawArrow(gs as Sel, CX - 60 + 20, addRowY, CX + 320 - 70 - 4, addRowY, { color: COLORS.out.stroke });

    shapeEq(gs, CX, addRowY + MAT_H / 2 + 24,
      `sum = text + gated  →  [${seqLen}, ${dModel}]  (residual connection preserves text)`, COLORS.out.stroke);

    // Sub-row C: LayerNorm → output
    const lnY = addRowY + MAT_H / 2 + 24 + ROW_GAP * 0.6;
    arrowDown(gs, CX + 320, addRowY + MAT_H / 2, lnY - 15, COLORS.norm.stroke);
    lnBadge(gs, CX + 320, lnY);

    const outY = lnY + 15 + ROW_GAP * 0.8;
    arrowDown(gs, CX + 320, lnY + 15, outY - MAT_H / 2, COLORS.out.stroke);
    seqMatrix(gs, CX, outY, 'output', `[${seqLen}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 220, MAT_H);
    shapeEq(gs, CX, outY + MAT_H / 2 + 24,
      `output = LayerNorm(text + gate ⊙ attn_proj)  →  [${seqLen}, ${dModel}]`, COLORS.out.stroke);

    steps.push(makeStep(stepId, 'Gate', 'Gated Residual Fusion',
      `LN(text + gate ⊙ attn_proj)`,
      'Gated residual: a learned gate controls how much visual information flows into text, preserving the text representation.',
      'step-gate', COLORS.gate.stroke, COLORS.gate.fill,
      [`gate = sigmoid(W_g @ text)             # learned gate`,
       `gated = gate * attn_proj             # element-wise`,
       `output = LayerNorm(text + gated)     # [${seqLen}, ${dModel}]`]));
    y = outY + MAT_H / 2 + 24;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// MLP Projector (LLaVA-style) — 6 steps
// ═══════════════════════════════════════════════════════════════════════════════

function renderMLPProjector(
  g: Gsel, startY: number, seqLen: number, nPatches: number, dModel: number
): { steps: VlStep[]; y: number } {
  const steps: VlStep[] = [];
  let stepId = 0;
  let y = startY;
  const dFF = dModel * 2;

  // ── Step 1: Input ──────────────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-input', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Input Representations',
      `text: [${seqLen}, ${dModel}]   image: [${nPatches}, ${dModel}]`,
      COLORS.text.fill, COLORS.text.stroke);

    const rowY = h + BOX_TO_ROW;
    seqMatrix(gs, CX - 200, rowY, 'text', `[${seqLen}, ${dModel}]`, COLORS.text.fill, COLORS.text.stroke);
    lbl(gs, CX - 200, rowY - MAT_H / 2 - 12, 'Text Tokens', { size: 9, color: COLORS.text.stroke, weight: '600' });
    seqMatrix(gs, CX + 200, rowY, 'image', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke);
    lbl(gs, CX + 200, rowY - MAT_H / 2 - 12, 'Image Tokens', { size: 9, color: COLORS.img.stroke, weight: '600' });

    steps.push(makeStep(stepId, 'Input', 'Input Representations',
      `text [${seqLen}, ${dModel}], image [${nPatches}, ${dModel}]`,
      'Text and image token sequences from their respective encoders.',
      'step-input', COLORS.text.stroke, COLORS.text.fill));
    y = rowY + MAT_H / 2 + STEP_GAP;
  }

  // ── Step 2: FC1 (expand to 2×d) ───────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-fc1', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Linear Projection FC1 (Expand)',
      `h = image · W_1 + b_1  →  [${nPatches}, ${dFF}]  (d_model × 2)`,
      COLORS.proj.fill, COLORS.proj.stroke);

    arrowDown(gs, CX + 200, y, h, COLORS.img.stroke);

    const rowY = h + BOX_TO_ROW;
    matmulRow(gs, CX, rowY,
      'image', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke,
      'W_1', `[${dModel}, ${dFF}]`, COLORS.weight.fill, COLORS.proj.stroke,
      'h', `[${nPatches}, ${dFF}]`, COLORS.proj.fill, COLORS.proj.stroke,
      160, 140, 170);

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `image [${nPatches}, ${dModel}] · W_1 [${dModel}, ${dFF}] + b_1 = h [${nPatches}, ${dFF}]`, COLORS.proj.stroke);

    steps.push(makeStep(stepId, 'FC1', 'Linear FC1 (Expand)',
      `image · W_1 → [${nPatches}, ${dFF}]`,
      `Expands image features from d_model=${dModel} to ${dFF} (2× expansion) for richer representation.`,
      'step-fc1', COLORS.proj.stroke, COLORS.proj.fill,
      [`h = image @ W_1 + b_1   # [${nPatches}, ${dFF}]`]));
    y = rowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 3: GELU activation ───────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-gelu', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'GELU Activation',
      `h_act = GELU(h)  →  [${nPatches}, ${dFF}]`,
      COLORS.gate.fill, COLORS.gate.stroke);

    arrowDown(gs, CX, y, h, COLORS.proj.stroke);

    const badgeY = h + BOX_TO_ROW;
    seqMatrix(gs, CX - 180, badgeY, 'h', `[${nPatches}, ${dFF}]`, COLORS.proj.fill, COLORS.proj.stroke, 170, MAT_H);
    activationBadge(gs, CX, badgeY, 'GELU', COLORS.gate.fill, COLORS.gate.stroke);
    drawArrow(gs as Sel, CX - 180 + 85 + 4, badgeY, CX - 65 - 4, badgeY, { color: COLORS.gate.stroke });
    seqMatrix(gs, CX + 180, badgeY, 'h_act', `[${nPatches}, ${dFF}]`, COLORS.gate.fill, COLORS.gate.stroke, 170, MAT_H);
    drawArrow(gs as Sel, CX + 65 + 4, badgeY, CX + 180 - 85 - 4, badgeY, { color: COLORS.gate.stroke });

    shapeEq(gs, CX, badgeY + MAT_H / 2 + 24,
      `h_act = GELU(h)  →  [${nPatches}, ${dFF}]  (smooth non-linearity)`, COLORS.gate.stroke);

    steps.push(makeStep(stepId, 'GELU', 'GELU Activation', `GELU(h)`,
      'GELU provides smooth gradients for better training stability compared to ReLU.',
      'step-gelu', COLORS.gate.stroke, COLORS.gate.fill,
      [`h_act = F.gelu(h)   # [${nPatches}, ${dFF}]`]));
    y = badgeY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 4: FC2 (project back to d_model) ─────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-fc2', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Linear Projection FC2 (Compress)',
      `proj = h_act · W_2 + b_2  →  [${nPatches}, ${dModel}]`,
      COLORS.proj.fill, COLORS.proj.stroke);

    arrowDown(gs, CX, y, h, COLORS.gate.stroke);

    const rowY = h + BOX_TO_ROW;
    matmulRow(gs, CX, rowY,
      'h_act', `[${nPatches}, ${dFF}]`, COLORS.gate.fill, COLORS.gate.stroke,
      'W_2', `[${dFF}, ${dModel}]`, COLORS.weight.fill, COLORS.proj.stroke,
      'proj', `[${nPatches}, ${dModel}]`, COLORS.proj.fill, COLORS.proj.stroke,
      170, 140, 170);

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `h_act [${nPatches}, ${dFF}] · W_2 [${dFF}, ${dModel}] + b_2 = proj [${nPatches}, ${dModel}]`, COLORS.proj.stroke);

    steps.push(makeStep(stepId, 'FC2', 'Linear FC2 (Compress)',
      `h_act · W_2 → [${nPatches}, ${dModel}]`,
      `Compresses back from ${dFF} to d_model=${dModel} to match the language model dimension.`,
      'step-fc2', COLORS.proj.stroke, COLORS.proj.fill,
      [`proj = h_act @ W_2 + b_2   # [${nPatches}, ${dModel}]`]));
    y = rowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 5: LayerNorm ─────────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-ln', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Layer Normalization',
      `img_proj = LayerNorm(proj)  →  [${nPatches}, ${dModel}]`,
      COLORS.norm.fill, COLORS.norm.stroke);

    arrowDown(gs, CX, y, h, COLORS.proj.stroke);

    const rowY = h + BOX_TO_ROW;
    seqMatrix(gs, CX - 180, rowY, 'proj', `[${nPatches}, ${dModel}]`, COLORS.proj.fill, COLORS.proj.stroke, 170, MAT_H);
    lnBadge(gs, CX, rowY);
    drawArrow(gs as Sel, CX - 180 + 85 + 4, rowY, CX - 65 - 4, rowY, { color: COLORS.norm.stroke });
    seqMatrix(gs, CX + 180, rowY, 'img_proj', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke, 170, MAT_H);
    drawArrow(gs as Sel, CX + 65 + 4, rowY, CX + 180 - 85 - 4, rowY, { color: COLORS.norm.stroke });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `img_proj = LayerNorm(proj)  →  [${nPatches}, ${dModel}]  (stabilizes training)`, COLORS.norm.stroke);

    steps.push(makeStep(stepId, 'LN', 'LayerNorm', `LN(proj)`,
      'Normalizes the projected image features to stabilize training and match text token statistics.',
      'step-ln', COLORS.norm.stroke, COLORS.norm.fill,
      [`img_proj = LayerNorm(proj)   # [${nPatches}, ${dModel}]`]));
    y = rowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 6: Concat + Output ───────────────────────────────────────────────
  stepId++;
  {
    const totalLen = seqLen + nPatches;
    const gs = startGroup(g, 'step-concat', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Concatenate + Output Projection',
      `out = concat(text, img_proj) · W_out  →  [${totalLen}, ${dModel}]`,
      COLORS.out.fill, COLORS.out.stroke);

    arrowDown(gs, CX - 200, y, h, COLORS.text.stroke);
    arrowDown(gs, CX + 180, y, h, COLORS.img.stroke);

    // Two inputs side by side
    const rowY = h + BOX_TO_ROW;
    seqMatrix(gs, CX - 200, rowY, 'text', `[${seqLen}, ${dModel}]`, COLORS.text.fill, COLORS.text.stroke, 160, MAT_H);
    lbl(gs, CX, rowY, '‖', { size: 24, weight: '700', color: COLORS.out.stroke });
    seqMatrix(gs, CX + 200, rowY, 'img_proj', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke, 170, MAT_H);

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `concat(text [${seqLen}, ${dModel}], img_proj [${nPatches}, ${dModel}]) = fused [${totalLen}, ${dModel}]`,
      COLORS.out.stroke);

    // Output projection
    const outRowY = rowY + MAT_H / 2 + 24 + ROW_GAP + MAT_H / 2;
    arrowDown(gs, CX, rowY + MAT_H / 2, outRowY - MAT_H / 2, COLORS.out.stroke);

    matmulRow(gs, CX, outRowY,
      'fused', `[${totalLen}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke,
      'W_out', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.out.stroke,
      'output', `[${totalLen}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke,
      170, WEIGHT_W, 180);

    shapeEq(gs, CX, outRowY + MAT_H / 2 + 24,
      `concat(text, img_proj) · W_out = output [${totalLen}, ${dModel}]`, COLORS.out.stroke);

    steps.push(makeStep(stepId, 'Concat', 'Concat + Output',
      `concat · W_out → [${totalLen}, ${dModel}]`,
      `Concatenate projected image with text tokens (${seqLen}+${nPatches}=${totalLen}), then project.`,
      'step-concat', COLORS.out.stroke, COLORS.out.fill,
      [`fused = torch.cat([text, img_proj], dim=1)  # [${totalLen}, ${dModel}]`,
       `output = fused @ W_out                     # [${totalLen}, ${dModel}]`]));
    y = outRowY + MAT_H / 2 + 24;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Perceiver Resampler — 6 steps
// ═══════════════════════════════════════════════════════════════════════════════

function renderPerceiverResampler(
  g: Gsel, startY: number, seqLen: number, nPatches: number,
  dModel: number, nHeads: number, nLatents: number
): { steps: VlStep[]; y: number } {
  const steps: VlStep[] = [];
  let stepId = 0;
  let y = startY;
  const dHead = Math.floor(dModel / nHeads);

  // ── Step 1: Input + Latent Queries ─────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-input', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Input + Learned Latent Queries',
      `text [${seqLen}, ${dModel}]   image [${nPatches}, ${dModel}]   latents [${nLatents}, ${dModel}]`,
      COLORS.latent.fill, COLORS.latent.stroke);

    const rowY = h + BOX_TO_ROW;
    seqMatrix(gs, CX - 280, rowY, 'text', `[${seqLen}, ${dModel}]`, COLORS.text.fill, COLORS.text.stroke, 150, MAT_H);
    lbl(gs, CX - 280, rowY - MAT_H / 2 - 12, 'Text Tokens', { size: 9, color: COLORS.text.stroke, weight: '600' });
    seqMatrix(gs, CX, rowY, 'image', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke, 160, MAT_H);
    lbl(gs, CX, rowY - MAT_H / 2 - 12, 'Image Tokens', { size: 9, color: COLORS.img.stroke, weight: '600' });
    seqMatrix(gs, CX + 280, rowY, 'latents', `[${nLatents}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 160, MAT_H);
    lbl(gs, CX + 280, rowY - MAT_H / 2 - 12, 'Learned Queries', { size: 9, color: COLORS.latent.stroke, weight: '600' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `latents are nn.Parameter(${nLatents}, ${dModel}), expanded to batch size at runtime`, COLORS.latent.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input + Latent Queries',
      `latents [${nLatents}, ${dModel}]`,
      `${nLatents} learned latent queries will cross-attend to ${nPatches} image features to produce a fixed-size visual summary.`,
      'step-input', COLORS.latent.stroke, COLORS.latent.fill));
    y = rowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 2: Block 1 QKV ───────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-ca1-qkv', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Block 1: Q from Latents, K/V from Image',
      `Q = latents · W_q  K = image · W_k  V = image · W_v  (${nHeads} heads, d_head=${dHead})`,
      COLORS.attn.fill, COLORS.attn.stroke);

    arrowDown(gs, CX + 280, y, h - 30, COLORS.latent.stroke);
    arrowDown(gs, CX, y, h - 30, COLORS.img.stroke);

    // Q from latents
    const qRowY = h + BOX_TO_ROW;
    lbl(gs, CX, qRowY - MAT_H / 2 - 14, 'Q source: learned latents', { size: 8, color: COLORS.latent.stroke, weight: '600' });
    matmulRow(gs, CX, qRowY,
      'latents', `[${nLatents}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke,
      'W_q', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.attn.stroke,
      'Q', `[${nLatents}, ${dModel}]`, COLORS.latent.fill, COLORS.attn.stroke,
      160, WEIGHT_W, 160);

    // K from image
    const kRowY = qRowY + MAT_H / 2 + 24 + ROW_GAP * 0.7 + MAT_H / 2;
    arrowDown(gs, CX - 240, qRowY + MAT_H / 2, kRowY - MAT_H / 2, COLORS.img.stroke);
    lbl(gs, CX, kRowY - MAT_H / 2 - 14, 'K,V source: image tokens', { size: 8, color: COLORS.img.stroke, weight: '600' });
    matmulRow(gs, CX, kRowY,
      'image', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke,
      'W_k', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.attn.stroke,
      'K', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.attn.stroke,
      160, WEIGHT_W, 160);

    // V from image
    const vRowY = kRowY + MAT_H / 2 + 24 + ROW_GAP * 0.7 + MAT_H / 2;
    arrowDown(gs, CX - 240, kRowY + MAT_H / 2, vRowY - MAT_H / 2, COLORS.img.stroke);
    matmulRow(gs, CX, vRowY,
      'image', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke,
      'W_v', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.attn.stroke,
      'V', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.attn.stroke,
      160, WEIGHT_W, 160);

    shapeEq(gs, CX, vRowY + MAT_H / 2 + 24,
      `Q [${nLatents}, ${dModel}], K [${nPatches}, ${dModel}], V [${nPatches}, ${dModel}]`, COLORS.attn.stroke);

    steps.push(makeStep(stepId, 'B1-QKV', 'Block 1: QKV Projections',
      `Q=latents·W_q, K,V=image·W_k,W_v`,
      'Latent queries provide Q; image features provide K and V for the first cross-attention.',
      'step-ca1-qkv', COLORS.attn.stroke, COLORS.attn.fill,
      [`Q = latents @ W_q   # [${nLatents}, ${dModel}]`,
       `K = image @ W_k     # [${nPatches}, ${dModel}]`,
       `V = image @ W_v     # [${nPatches}, ${dModel}]`]));
    y = vRowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 3: Block 1 attention + LN ────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-ca1-attn', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Block 1: Cross-Attention + LayerNorm',
      `attn_1 = LN(softmax(Q·K^T/√${dHead})·V)  →  [${nLatents}, ${dModel}]`,
      COLORS.attn.fill, COLORS.attn.stroke);

    arrowDown(gs, CX, y, h, COLORS.attn.stroke);

    // Score + softmax
    const scoreY = h + BOX_TO_ROW;
    shapeEq(gs, CX, scoreY,
      `Q [${nLatents}, ${dModel}] · K^T [${dModel}, ${nPatches}] / √${dHead} → scores [${nLatents}, ${nPatches}]`,
      COLORS.attn.stroke);

    const weightY = scoreY + 28 + ROW_GAP * 0.5;
    seqMatrix(gs, CX - 160, weightY, 'scores', `[${nLatents}, ${nPatches}]`, COLORS.attn.fill, COLORS.attn.stroke, 160, 56);
    lbl(gs, CX, weightY, 'softmax →', { size: 10, weight: '600', color: COLORS.attn.stroke });
    seqMatrix(gs, CX + 160, weightY, 'weights', `[${nLatents}, ${nPatches}]`, '#fff5f5', COLORS.attn.stroke, 160, 56);
    drawArrow(gs as Sel, CX - 160 + 80 + 4, weightY, CX - 40, weightY, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, CX + 40, weightY, CX + 160 - 80 - 4, weightY, { color: COLORS.attn.stroke });

    // Weighted sum
    const wvRowY = weightY + 40 + ROW_GAP * 0.7;
    matmulRow(gs, CX, wvRowY,
      'weights', `[${nLatents}, ${nPatches}]`, '#fff5f5', COLORS.attn.stroke,
      'V', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.attn.stroke,
      'attn_raw', `[${nLatents}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke,
      160, 120, 170);

    shapeEq(gs, CX, wvRowY + MAT_H / 2 + 24,
      `weights [${nLatents}, ${nPatches}] · V [${nPatches}, ${dModel}] = attn_raw [${nLatents}, ${dModel}]`,
      COLORS.attn.stroke);

    // LayerNorm
    const lnY = wvRowY + MAT_H / 2 + 24 + ROW_GAP * 0.6;
    arrowDown(gs, CX + 250, wvRowY + MAT_H / 2, lnY - 15, COLORS.attn.stroke);
    lnBadge(gs, CX + 250, lnY);

    const outY = lnY + 15 + ROW_GAP * 0.8;
    arrowDown(gs, CX + 250, lnY + 15, outY - MAT_H / 2, COLORS.norm.stroke);
    seqMatrix(gs, CX, outY, 'attn_1', `[${nLatents}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 180, MAT_H);
    shapeEq(gs, CX, outY + MAT_H / 2 + 24,
      `attn_1 = LayerNorm(weights · V)  →  [${nLatents}, ${dModel}]  (compressed visual summary)`, COLORS.norm.stroke);

    steps.push(makeStep(stepId, 'B1-Attn', 'Block 1: Cross-Attention',
      `LN(softmax(QK^T/√d)·V)`,
      `First cross-attention: ${nLatents} latent queries attend to ${nPatches} image features, compressing them.`,
      'step-ca1-attn', COLORS.attn.stroke, COLORS.attn.fill,
      [`scores = Q @ K.T / sqrt(${dHead})   # [${nHeads}, ${nLatents}, ${nPatches}]`,
       `weights = softmax(scores, dim=-1)`,
       `attn_1 = LayerNorm(weights @ V)     # [${nLatents}, ${dModel}]`]));
    y = outY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 4: Block 2 QKV ───────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-ca2-qkv', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Block 2: Q from attn_1, K/V from Image',
      `Q = attn_1 · W_q2  K = image · W_k2  V = image · W_v2`,
      COLORS.attn.fill, COLORS.attn.stroke);

    arrowDown(gs, CX, y, h, COLORS.attn.stroke);

    const qRowY = h + BOX_TO_ROW;
    lbl(gs, CX, qRowY - MAT_H / 2 - 14, 'Q source: attn_1 output from block 1', { size: 8, color: COLORS.attn.stroke, weight: '600' });
    matmulRow(gs, CX, qRowY,
      'attn_1', `[${nLatents}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke,
      'W_q2', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.attn.stroke,
      'Q', `[${nLatents}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke,
      160, WEIGHT_W, 160);

    const kRowY = qRowY + MAT_H / 2 + 24 + ROW_GAP * 0.7 + MAT_H / 2;
    arrowDown(gs, CX - 240, qRowY + MAT_H / 2, kRowY - MAT_H / 2, COLORS.img.stroke);
    lbl(gs, CX, kRowY - MAT_H / 2 - 14, 'K,V source: original image tokens', { size: 8, color: COLORS.img.stroke, weight: '600' });
    matmulRow(gs, CX, kRowY,
      'image', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke,
      'W_k2', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.attn.stroke,
      'K', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.attn.stroke,
      160, WEIGHT_W, 160);

    const vRowY = kRowY + MAT_H / 2 + 24 + ROW_GAP * 0.7 + MAT_H / 2;
    arrowDown(gs, CX - 240, kRowY + MAT_H / 2, vRowY - MAT_H / 2, COLORS.img.stroke);
    matmulRow(gs, CX, vRowY,
      'image', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke,
      'W_v2', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.attn.stroke,
      'V', `[${nPatches}, ${dModel}]`, COLORS.img.fill, COLORS.attn.stroke,
      160, WEIGHT_W, 160);

    shapeEq(gs, CX, vRowY + MAT_H / 2 + 24,
      `Q [${nLatents}, ${dModel}], K [${nPatches}, ${dModel}], V [${nPatches}, ${dModel}]`, COLORS.attn.stroke);

    steps.push(makeStep(stepId, 'B2-QKV', 'Block 2: QKV Projections',
      `Q=attn_1·W_q2, K,V=image·W_k2,W_v2`,
      'Second block: Q from refined attention output, K/V still from original image for further refinement.',
      'step-ca2-qkv', COLORS.attn.stroke, COLORS.attn.fill,
      [`Q = attn_1 @ W_q2   # [${nLatents}, ${dModel}]`,
       `K = image @ W_k2     # [${nPatches}, ${dModel}]`,
       `V = image @ W_v2     # [${nPatches}, ${dModel}]`]));
    y = vRowY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 5: Block 2 attention + residual + LN ─────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-ca2-res', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Block 2: Attention + Residual + LayerNorm',
      `vision = LN(softmax(Q·K^T/√${dHead})·V + attn_1)  →  [${nLatents}, ${dModel}]`,
      COLORS.attn.fill, COLORS.attn.stroke);

    arrowDown(gs, CX, y, h, COLORS.attn.stroke);

    // Score + softmax (compact)
    const scoreY = h + BOX_TO_ROW;
    shapeEq(gs, CX, scoreY,
      `softmax(Q·K^T/√${dHead})·V → ca2_out [${nLatents}, ${dModel}]`, COLORS.attn.stroke);

    // Residual add
    const addRowY = scoreY + 28 + ROW_GAP;
    seqMatrix(gs, CX - 200, addRowY, 'ca2_out', `[${nLatents}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 160, MAT_H);
    opCircle(gs, CX - 20, addRowY, '+', COLORS.gate.stroke);
    drawArrow(gs as Sel, CX - 200 + 80 + 4, addRowY, CX - 20 - 20, addRowY, { color: COLORS.attn.stroke });

    seqMatrix(gs, CX + 160, addRowY, 'attn_1', `[${nLatents}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 150, MAT_H);
    lbl(gs, CX + 80, addRowY - 14, 'residual', { size: 7, color: COLORS.gate.stroke });
    drawArrow(gs as Sel, CX + 160 - 75 - 4, addRowY, CX - 20 + 20, addRowY, { color: COLORS.gate.stroke });

    seqMatrix(gs, CX + 330, addRowY, 'sum', `[${nLatents}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 130, MAT_H);
    drawArrow(gs as Sel, CX - 20 + 20, addRowY, CX + 330 - 65 - 4, addRowY, { color: COLORS.out.stroke });

    shapeEq(gs, CX, addRowY + MAT_H / 2 + 24,
      `sum = ca2_out + attn_1  →  [${nLatents}, ${dModel}]  (skip connection)`, COLORS.gate.stroke);

    // LayerNorm
    const lnY = addRowY + MAT_H / 2 + 24 + ROW_GAP * 0.6;
    arrowDown(gs, CX + 330, addRowY + MAT_H / 2, lnY - 15, COLORS.norm.stroke);
    lnBadge(gs, CX + 330, lnY);

    const outY = lnY + 15 + ROW_GAP * 0.8;
    arrowDown(gs, CX + 330, lnY + 15, outY - MAT_H / 2, COLORS.norm.stroke);
    seqMatrix(gs, CX, outY, 'vision_tokens', `[${nLatents}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke, 200, MAT_H);
    shapeEq(gs, CX, outY + MAT_H / 2 + 24,
      `vision_tokens = LN(ca2_out + attn_1)  →  [${nLatents}, ${dModel}]  (fixed-size visual summary)`, COLORS.img.stroke);

    steps.push(makeStep(stepId, 'B2-Res', 'Block 2: Attn + Residual',
      `LN(CA + attn_1)`,
      'Residual connection preserves information from block 1 while adding refined cross-attention output.',
      'step-ca2-res', COLORS.attn.stroke, COLORS.attn.fill,
      [`ca2_out = softmax(Q @ K.T / sqrt(${dHead})) @ V`,
       `vision_tokens = LayerNorm(ca2_out + attn_1)  # [${nLatents}, ${dModel}]`]));
    y = outY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 6: Gated fusion with text ────────────────────────────────────────
  stepId++;
  {
    const totalLen = seqLen + nLatents;
    const gs = startGroup(g, 'step-fuse', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Gated Fusion with Text',
      `out = concat(text_proj, gate ⊙ vision) · W_out  →  [${totalLen}, ${dModel}]`,
      COLORS.gate.fill, COLORS.gate.stroke);

    arrowDown(gs, CX - 280, y, h - 20, COLORS.text.stroke);
    arrowDown(gs, CX, y, h - 20, COLORS.img.stroke);

    // Gate vision tokens
    const gateRowY = h + BOX_TO_ROW;
    seqMatrix(gs, CX - 80, gateRowY, 'vision', `[${nLatents}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke, 160, MAT_H);
    opCircle(gs, CX + 60, gateRowY, '⊙', COLORS.gate.stroke);
    drawArrow(gs as Sel, CX - 80 + 80 + 4, gateRowY, CX + 60 - 20, gateRowY, { color: COLORS.gate.stroke });
    lbl(gs, CX + 60, gateRowY - 28, 'gate', { size: 8, color: COLORS.gate.stroke, weight: '600' });
    // gate vector
    const gateVecW = 100;
    g.append('rect').attr('x', CX + 170 - gateVecW / 2).attr('y', gateRowY - 16).attr('width', gateVecW).attr('height', 32)
      .attr('rx', 4).attr('fill', COLORS.gate.fill).attr('stroke', COLORS.gate.stroke).attr('stroke-width', 1);
    lbl(gs, CX + 170, gateRowY + 1, 'σ(W_g)', { size: 9, weight: '600', color: COLORS.gate.stroke });
    drawArrow(gs as Sel, CX + 170 - gateVecW / 2 - 4, gateRowY, CX + 60 + 20, gateRowY, { color: COLORS.gate.stroke });

    seqMatrix(gs, CX + 310, gateRowY, 'gated_v', `[${nLatents}, ${dModel}]`, COLORS.gate.fill, COLORS.gate.stroke, 160, MAT_H);
    drawArrow(gs as Sel, CX + 60 + 20, gateRowY, CX + 310 - 80 - 4, gateRowY, { color: COLORS.gate.stroke });

    shapeEq(gs, CX, gateRowY + MAT_H / 2 + 24,
      `gated_v = σ(W_g) ⊙ vision_tokens  →  [${nLatents}, ${dModel}]`, COLORS.gate.stroke);

    // Concat
    const catRowY = gateRowY + MAT_H / 2 + 24 + ROW_GAP;
    seqMatrix(gs, CX - 200, catRowY, 'text_proj', `[${seqLen}, ${dModel}]`, COLORS.text.fill, COLORS.text.stroke, 160, MAT_H);
    lbl(gs, CX, catRowY, '‖', { size: 24, weight: '700', color: COLORS.out.stroke });
    seqMatrix(gs, CX + 200, catRowY, 'gated_v', `[${nLatents}, ${dModel}]`, COLORS.gate.fill, COLORS.gate.stroke, 160, MAT_H);

    shapeEq(gs, CX, catRowY + MAT_H / 2 + 24,
      `concat(text [${seqLen}, ${dModel}], gated_v [${nLatents}, ${dModel}]) = fused [${totalLen}, ${dModel}]`,
      COLORS.out.stroke);

    // Output projection
    const outRowY = catRowY + MAT_H / 2 + 24 + ROW_GAP + MAT_H / 2;
    arrowDown(gs, CX, catRowY + MAT_H / 2, outRowY - MAT_H / 2, COLORS.out.stroke);
    matmulRow(gs, CX, outRowY,
      'fused', `[${totalLen}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke,
      'W_out', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.out.stroke,
      'output', `[${totalLen}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke,
      170, WEIGHT_W, 180);

    shapeEq(gs, CX, outRowY + MAT_H / 2 + 24,
      `fused · W_out = output [${totalLen}, ${dModel}]  (final fused representation)`, COLORS.out.stroke);

    steps.push(makeStep(stepId, 'Fuse', 'Gated Fusion with Text',
      `concat · W_out → [${totalLen}, ${dModel}]`,
      `Gate vision tokens then concatenate with text (${seqLen}+${nLatents}=${totalLen}). Compact visual summary + full text.`,
      'step-fuse', COLORS.gate.stroke, COLORS.gate.fill,
      [`gated_v = sigmoid(W_g @ text) * vision   # [${nLatents}, ${dModel}]`,
       `fused = concat(text_proj, gated_v)      # [${totalLen}, ${dModel}]`,
       `output = fused @ W_out                 # [${totalLen}, ${dModel}]`]));
    y = outRowY + MAT_H / 2 + 24;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Entry point
// ═══════════════════════════════════════════════════════════════════════════════

export function renderVlFusionDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const seqLen = Number(params.seq_len) || 128;
  const nPatches = Number(params.n_patches) || 196;
  const dModel = Number(params.d_model) || 768;
  const nHeads = Number(params.n_heads) || 8;
  const nLatents = Number(params.n_latents) || 64;
  const variant = String(params.variant || 'cross-attention');

  let y = 10;

  lbl(g, CX, y + 14, 'VL Fusion', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  const variantLabel =
    variant === 'cross-attention' ? 'Cross-Attention (Flamingo)' :
    variant === 'mlp-projector' ? 'MLP Projector (LLaVA)' :
    'Perceiver Resampler';
  lbl(g, CX, y + 8, `Fuse vision and language representations — ${variantLabel}`, { size: 10, color: 'var(--text-muted)' });
  y += 28;

  const dHead = Math.floor(dModel / nHeads);
  const summaryItems = [`seq: ${seqLen}`, `patches: ${nPatches}`, `d_model: ${dModel}`, `heads: ${nHeads} (d_h=${dHead})`];
  if (variant === 'perceiver-resampler') summaryItems.push(`latents: ${nLatents}`);
  y = paramSummary(g, CX, y, summaryItems);
  y += 28;

  let result: { steps: VlStep[]; y: number };
  if (variant === 'mlp-projector') {
    result = renderMLPProjector(g, y, seqLen, nPatches, dModel);
  } else if (variant === 'perceiver-resampler') {
    result = renderPerceiverResampler(g, y, seqLen, nPatches, dModel, nHeads, nLatents);
  } else {
    result = renderCrossAttention(g, y, seqLen, nPatches, dModel, nHeads);
  }
  const { steps } = result;
  y = result.y + 28;

  const explanations: Record<string, string> = {
    'cross-attention':
      'Flamingo-style cross-attention: text tokens generate queries that attend to image key/value pairs. ' +
      'A gated residual connection allows the model to selectively incorporate visual information while preserving text representations. ' +
      'This approach keeps the text sequence length unchanged.',
    'mlp-projector':
      'LLaVA-style MLP projection: a two-layer MLP with GELU activation projects image features to the language model dimension. ' +
      'Projected image tokens are concatenated with text tokens for joint processing. ' +
      'Simple but effective — the full sequence length becomes text + image tokens.',
    'perceiver-resampler':
      'Perceiver resampler uses learned latent queries to cross-attend to image features, producing a fixed-size visual summary regardless of input resolution. ' +
      'This compresses variable-length image tokens into a compact representation before fusing with text. ' +
      'Particularly useful for high-resolution images or video.',
  };
  y = drawExplanation(g as Sel, CX - (W - 120) / 2, y, W - 120, explanations[variant] || explanations['cross-attention'], 'insight');
  y += 20;

  drawComponentLink(g as Sel, CX - (W - 120) / 2, y, (W - 120) / 2 - 8, 56, 'attention', 'Attention');
  drawComponentLink(g as Sel, CX + 8, y, (W - 120) / 2 - 8, 56, 'vit-encoder', 'ViT Encoder');
  y += 72;

  const codeLines: Record<string, string[]> = {
    'cross-attention': [
      `class CrossAttentionFusion(nn.Module):`,
      `    def __init__(self, d_model=${dModel}, n_heads=${nHeads}):`,
      `        self.W_q = nn.Linear(${dModel}, ${dModel})  # text → Q`,
      `        self.W_k = nn.Linear(${dModel}, ${dModel})  # image → K`,
      `        self.W_v = nn.Linear(${dModel}, ${dModel})  # image → V`,
      `        self.W_o = nn.Linear(${dModel}, ${dModel})  # output proj`,
      ``,
      `    def forward(self, text, image):`,
      `        Q = self.W_q(text)       # [B, ${seqLen}, ${dModel}]`,
      `        K, V = self.W_k(image), self.W_v(image)`,
      `        attn = multi_head_cross_attn(Q, K, V, ${nHeads})`,
      `        gated = gate * self.W_o(attn)`,
      `        return LayerNorm(text + gated)`,
    ],
    'mlp-projector': [
      `class MLPProjector(nn.Module):`,
      `    def __init__(self, d_model=${dModel}):`,
      `        self.fc1 = nn.Linear(${dModel}, ${dModel * 2})`,
      `        self.fc2 = nn.Linear(${dModel * 2}, ${dModel})`,
      `        self.norm = nn.LayerNorm(${dModel})`,
      ``,
      `    def forward(self, text, image):`,
      `        h = F.gelu(self.fc1(image))        # [B, ${nPatches}, ${dModel * 2}]`,
      `        img_proj = self.norm(self.fc2(h))  # [B, ${nPatches}, ${dModel}]`,
      `        fused = torch.cat([text, img_proj], dim=1)`,
      `        return fused @ self.W_out  # [B, ${seqLen + nPatches}, ${dModel}]`,
    ],
    'perceiver-resampler': [
      `class PerceiverResampler(nn.Module):`,
      `    def __init__(self, d_model=${dModel}, n_latents=${nLatents}, n_heads=${nHeads}):`,
      `        self.latents = nn.Parameter(torch.randn(${nLatents}, ${dModel}))`,
      `        # 2 cross-attention blocks + gated fusion`,
      ``,
      `    def forward(self, text, image):`,
      `        latents = self.latents.expand(B, -1, -1)`,
      `        # Block 1: latents cross-attend to image`,
      `        attn_1 = LN(cross_attn(Q=latents, K=image, V=image))`,
      `        # Block 2: refine with residual`,
      `        vision = LN(cross_attn(Q=attn_1, K=image, V=image) + attn_1)`,
      `        # Gated fusion with text`,
      `        fused = concat(text_proj, gate * vision)`,
      `        return fused @ W_out  # [B, ${seqLen + nLatents}, ${dModel}]`,
    ],
  };
  drawCodeAnnotation(g as Sel, CX - (W - 120) / 2, y, W - 120,
    `VL Fusion — ${variantLabel} (PyTorch)`,
    [`${variantLabel}: fuses ${nPatches} image + ${seqLen} text tokens → ${dModel}-dim output`],
    codeLines[variant] || codeLines['cross-attention']);

  return { width: W, height: y + 24, steps };
}
